def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    old_char = board[row][col]
    new_char = 'g' if old_char == 'N' else 'N'

    # Find the range of cells to change
    range_start = max(0, row - 1)
    range_end = min(63, row + 2)

    for i in range(range_start, range_end):
        for j in range(col - 1, col + 2):
            if 0 <= j < 64:
                if i == row and j == col:
                    board[i][j] = new_char
                elif j == col:
                    board[i][j] = 'g' if board[i][j] == 'N' else 'N'

    return ["".join(row) for row in board]
